bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 30
docker exec -i "$cid" node --input-type=module <<'NODE'
import fs from 'node:fs';import pg from 'pg';
const pool=new pg.Pool({host:process.env.VIDEOBOT_DB_HOST,user:process.env.VIDEOBOT_DB_USER,database:process.env.VIDEOBOT_DB_NAME,password:fs.readFileSync('/run/secrets/videobot_db_password','utf8').trim(),max:1,connectionTimeoutMillis:4500});
try{
 const columns=(await pool.query("SELECT column_name FROM information_schema.columns WHERE table_schema='public' AND table_name='videobot_stars_ledger'")).rows.map(x=>x.column_name);
 const col=x=>columns.includes(x);
 const r=await pool.query(`SELECT 
  COUNT(*)::int AS payment_count,
  COUNT(DISTINCT delivery_key)::int AS delivery_keys,
  COUNT(DISTINCT buyer_user_id)::int AS buyers,
  COUNT(*) FILTER (WHERE telegram_transaction_id IS NOT NULL)::int AS telegram_receipts,
  COUNT(*) FILTER (WHERE kind='paid')::int AS paid_rows
 FROM videobot_stars_ledger`);
 const x=r.rows[0];
 let mask=0;
 if(x.payment_count>0)mask|=1;
 if(x.delivery_keys===1)mask|=2;
 if(x.buyers===1)mask|=4;
 if(x.buyers>1)mask|=8;
 if(x.telegram_receipts===x.payment_count)mask|=16;
 if(x.paid_rows===x.payment_count)mask|=32;
 if(col('paid_media_payload'))mask|=64;
 if(col('buyer_user_id'))mask|=128;
 process.exitCode=mask;
}finally{await pool.end()}
NODE
